perform: Perform = async (action, success) => {
    if (busyRef.current) return false;
    busyRef.current = true;
    setBusy(true);
    setNotice(null);
    try {
      await refreshPending.current?.catch(() => {});
      await action();
      if (success) setNotice({ text: success, error: false });
      return true;
    } catch (error) {
      const copy =
        error instanceof PlatformError ? errorCopy[error.code] : undefined;
      setNotice({
        text: copy
          ? t(...copy)
          : t(
              "Не получилось. Попробуйте ещё раз.",
              "Something went wrong. Please try again.",
            ),
        error: true,
      });
      await refresh().catch(() => setOffline(true));
      return false;
    } finally {
      busyRef.current = false;
      setBusy(false);
    }
  }

