export async function request<T>(path: string, body?: unknown): Promise<T> {
  const method = body === undefined ? "GET" : "POST";
  const signature = `${path}:${JSON.stringify(body)}`;
  const headers: Record<string, string> = { Accept: "application/json" };
  if (method === "POST") {
    if (!csrfToken)
      throw new PlatformError(
        "SESSION_REQUIRED",
        "Refresh the page and try again.",
      );
    headers["Content-Type"] = "application/json";
    headers["X-CSRF-Token"] = csrfToken;
    if (!retryKeys.has(signature))
      retryKeys.set(signature, crypto.randomUUID());
    headers["Idempotency-Key"] = retryKeys.get(signature)!;
  }
  let response: Response;
  try {
    response = await fetch(`/api/platform/v1${path}`, {
      method,
      credentials: "same-origin",
      cache: "no-store",
      headers,
      ...(method === "POST" ? { body: JSON.stringify(body) } : {}),
      signal: AbortSignal.timeout(20_000),
    });
  } catch {
    throw new PlatformError(
      "NETWORK",
      "Connection interrupted. Retry the action.",
    );
  }
  const result = (await response.json().catch(() => null)) as
    | (T & { error?: { code?: string; message?: string } })
    | null;
  // A server failure or unreadable success can follow a committed mutation.
  // Keep the same key when the user retries that uncertain outcome.
  if (result !== null && response.status < 500) retryKeys.delete(signature);
  if (!response.ok)
    throw new PlatformError(
      result?.error?.code || "HTTP_ERROR",
      result?.error?.message || "Request failed.",
      response.status,
    );
  if (result === null)
    throw new PlatformError(
      "INVALID_RESPONSE",
      "The server returned an unreadable response.",
    );
  return result;
}

export function getSession(): Promise<Session> {
  // Multiple React mounts must not race to create different anonymous cookies.
  if (sessionRequest) return sessionRequest;
  sessionRequest = request<Session>("/session")
    .then((session) => {
      csrfToken = session.csrfToken;
      return session;
    })
    .finally(() => {
      sessionRequest = null;
    });
  return sessionRequest;
}

export function go(page: Page, roomId?: string, replace = false): void {
  navigate(page === "home" ? "/" : `/${page}${roomId ? `/${encodeURIComponent(roomId)}` : ""}`, replace);
}

export function navigate(href: string, replace = false): void {
  if (replace) history.replaceState(null, "", href);
  else history.pushState(null, "", href);
  window.dispatchEvent(new PopStateEvent("popstate"));
}

export function readRoute(): Route {
  const url = new URL(window.location.href);
  // Keep previously shared room/invitation links working.
  const path = url.hash.startsWith("#/") ? url.hash.slice(1) : url.pathname;
  const bits = path.split("/").filter(Boolean);
  if (["invite", "invites", "invitations"].includes(bits[0] ?? "") && bits[1])
    return { page: "invitations", invitationId: bits[1] };
  if (bits[0] === "rooms") return { page: "rooms", roomId: bits[1] };
  if (["login", "verify", "reset"].includes(bits[0] ?? "")) return { page: "login" };
  return { page: ["chess", "games", "friends", "invitations", "profile"].includes(bits[0] ?? "")
    ? bits[0] as Page : "home" };
}

function gameReturnPath() {
  const path = new URLSearchParams(location.search).get('returnTo');
  return path && Object.values(realtimeRoutes).some(route => path === route) ? path : null;
}

export function readEntrance(): Entrance {
  const url = new URL(window.location.href);
  const token = url.searchParams.get("token");
  if (!token) return null;
  const kind = /reset/.test(url.pathname)
    ? "reset"
    : /verify/.test(url.pathname)
      ? "verify"
      : null;
  if (!kind) return null;
  url.searchParams.delete("token");
  history.replaceState(null, "", `${url.pathname}${url.search}${url.hash}`);
  return { kind, token };
}

